import React, { useEffect, useState } from 'react';
//gracias a esto solo se trae lo que se necesita no todo.
import {
     Button, Modal, ModalHeader, ModalBody, 
     ModalFooter, Form, Formgroup, Label, Input } from 'reactstrap';


const CursoList = () => {

    //declaracion de variables, arreglos
    const [cursos, setCursos] = useState([]);
    const [modalOpen, setModalOpen] = useState(false);




    //Ejecuta funciones, renderiza la pantalla, ejecuta scripts
    useEffect(() =>{
        fetchCursos();
    }, []);



    //Declarar funciones.
    const fetchCursos = () =>{
        //url + listar esto es la url del servicio concatenada
        fetch( 'https://paginas-web-cr.com/Api/apis/ListaCurso.php' )
        .then(respuesta=>respuesta.json())
        .then( (datosrepuesta) => {
            setCursos(datosrepuesta.data);
        })
        .catch(
            error=>{
                console.error('Error al cargar:' , error);
            }
        );
    };

    const toggleEditModal= (curso) => {
        setModalOpen(true);
    }

//https://paginas-web-cr.com/Api/apis/ListaCurso.php
    return ( 

        <div className='container'>
            <br></br> <br></br> <br></br>
                <Button color='dark' onClick={() => toggleEditModal(null)}> 
                    Agregar
                </Button>

                <table className="table table-info">

                                <thead>
                                    <tr>
                                        <th scope="col">Acciones</th>
                                        <th scope="col">Id</th>
                                        <th scope="col">Nombre</th>
                                        <th scope="col">Descripcion</th>
                                        <th scope="col">Tiempo</th>
                                        <th scope="col">Usuario</th>

                                    </tr>
                                </thead>
                                <tbody id="datos">
                                    {
                                        cursos.map( curso => (
                                                <tr key={curso.id}>
                                                    <td>Botones</td>
                                                    <td>{curso.id}</td>
                                                    <td>{curso.nombre}</td>
                                                    <td>{curso.descripcion}</td>
                                                    <td>{curso.tiempo}</td>
                                                    <td>{curso.usuario}</td>
                                                </tr>
                                        ))
                                    }

                                </tbody>
                            </table>

        <Modal isOpen = {modalOpen} > 

        <ModalHeader >Modal Curso</ModalHeader> 

        <ModalBody>
        <h1> Primer Modal</h1>
        </ModalBody>

        <ModalFooter>
        <Button color='primary' onClick={() => toggleEditModal(null)}>Guardar</Button>
        <Button color='secondary' onClick={() => toggleEditModal(false)}>Cerrar</Button>
        </ModalFooter>
        </Modal>    


        </div>



      );
}

export default CursoList;
